function resolveSubpath(exportsMap, subpath, condition) {
  const entry = Object.hasOwn(exportsMap, subpath) ? exportsMap[subpath] : undefined;
  if (typeof entry === "string") return entry;
  if (entry && typeof entry === "object") {
    for (const [key, target] of Object.entries(entry)) {
      if (key === condition || key === "default") return target;
    }
  }
  throw new Error(`ERR_PACKAGE_PATH_NOT_EXPORTED ${subpath}`);
}

const map = {
  ".": { import: "./esm/index.js", require: "./cjs/index.cjs" },
  "./money": "./src/money.js",
  "./legacy": { default: "./legacy.cjs", import: "./never.js" },
};
