questions.solution:
function findCycle(graph, start) {
  const path = [];
  const done = new Set();
  function visit(node) {
    const index = path.indexOf(node);
    if (index !== -1) return [...path.slice(index), node];
    if (done.has(node)) return null;
    path.push(node);
    for (const next of graph[node] ?? []) {
      const cycle = visit(next);
      if (cycle) return cycle;
    }
    path.pop();
    done.add(node);
    return null;
  }
  return visit(start);
}

const shop = {
  "main.js": ["orders.js", "logger.js"],
  "orders.js": ["payments.js", "logger.js"],
  "payments.js": ["base-payment.js"],
  "base-payment.js": ["card-payment.js"],
  "card-payment.js": ["base-payment.js"],
  "logger.js": [],
};
console.log(findCycle(shop, "main.js"));
console.log(findCycle({ "a.js": ["b.js"], "b.js": [] }, "a.js"));

