function detectExports(source) {
  const names = [];
  for (const match of source.matchAll(/(?:module\.)?exports\.([A-Za-z_$][\w$]*)\s*=/g)) {
    if (!names.includes(match[1])) names.push(match[1]);
  }
  return names;
}

const source = `
exports.charge = charge;
module.exports.refund = refund;
exports.charge = chargeV2;
for (const [name, fn] of Object.entries({ capture })) module.exports[name] = fn;
`;
